import { Form } from '@base-ui/react/form';
import { FieldControl as BaseControl } from './FieldControlBase';

afterEach(cleanup);

const variants: Array<[string, any]> = [
  ['HEAD', Field.Control],
  ['BASE', BaseControl],
];

function attrs(el: Element) {
  return Array.from(el.attributes)
    .map((a) => a.name)
    .filter((n) => n.startsWith('data-') && n !== 'data-testid')
    .sort()
    .join(',');
}

