      return (
        <Form
          onFormSubmit={() => {
            setValue('');
          }}
        >
          <Field.Root name="n" data-testid="root">
            <Control value={value} onValueChange={setValue} required />
            <Field.Error data-testid="err" />
          </Field.Root>
          <button type="submit">submit</button>
        </Form>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'abc' } });
    await act(async () => {
      fireEvent.click(screen.getByText('submit'));
    });
    await act(async () => {});
    console.log(label, '1 reset-after-submit root attrs:', attrs(screen.getByTestId('root')), 'err:', screen.queryByTestId('err')?.textContent);
  });

  it('2. value null typing', async () => {
    const validate = vi.fn(() => null);
    const spy = vi.spyOn(console, 'error').mockImplementation(() => {});
    render(
      <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
        <Control value={null as any} onValueChange={() => {}} />
      </Field.Root>,
    );
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'abc' } });
    await act(async () => {});
    console.log(label, '2 null value: attrs', attrs(screen.getByTestId('root')), 'validate calls', validate.mock.calls.length, 'dom', (screen.getByRole('textbox') as HTMLInputElement).value);
    spy.mockRestore();
  });

  it('3. controlled defaultPrevented', async () => {
    const validate = vi.fn(() => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ message: 'Server error' }}>
          <Field.Root name="message" validationMode="onChange" validate={validate}>
            <Control value={value} onValueChange={setValue} />
            <Field.Error data-testid="err" />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    const control = screen.getByRole<HTMLInputElement>('textbox');
    control.addEventListener('input', (event) => event.preventDefault(), { capture: true, once: true });
    fireEvent.input(control, { cancelable: true, target: { value: 'a' } });
    await act(async () => {});
    console.log(label, '3 prevented controlled: validate calls', validate.mock.calls.length, 'err', screen.queryByTestId('err')?.textContent, 'dom', control.value);
  });

  it('4. swap control filled stale', async () => {
    function App() {
      const [step, setStep] = React.useState(1);
      return (
        <Field.Root data-testid="root">
          {step === 1 ? (
            <Control key="a" value="hello" onValueChange={() => {}} />
          ) : (
            <Control key="b" value="" onValueChange={() => {}} />
          )}
          <button onClick={() => setStep(2)}>next</button>
        </Field.Root>
      );
    }
    render(<App />);
    console.log(label, '4 before swap', attrs(screen.getByTestId('root')));
    fireEvent.click(screen.getByText('next'));
    await act(async () => {});
    console.log(label, '4 after swap', attrs(screen.getByTestId('root')));
  });

  it('5. async load marks dirty / validates', async () => {
    const validate = vi.fn((v: unknown) => (v === 'bad' ? 'err' : null));
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Control value={value} onValueChange={setValue} />
          <Field.Error data-testid="err" />
          <button onClick={() => setValue('bad')}>load</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.click(screen.getByText('load'));
    await act(async () => {});
    console.log(label, '5 load', attrs(screen.getByTestId('root')), 'validate', validate.mock.calls.length, 'err', screen.queryByTestId('err')?.textContent);
  });

  it('6. cancel uncontrolled', async () => {
    const validate = vi.fn((v: unknown) => (v === 'bad' ? 'err' : null));
    render(
      <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
        <Control onValueChange={(v: string, d: any) => { if (v === 'good') d.cancel(); }} />
        <Field.Error data-testid="err" />
      </Field.Root>,
    );
    const control = screen.getByRole<HTMLInputElement>('textbox');
    fireEvent.change(control, { target: { value: 'bad' } });
    await act(async () => {});
    fireEvent.change(control, { target: { value: 'good' } });
    await act(async () => {});
    console.log(label, '6 cancel uncontrolled', attrs(screen.getByTestId('root')), 'dom', control.value, 'err', screen.queryByTestId('err')?.textContent);
  });

  it('7. cancel controlled but still set', async () => {
    const validate = vi.fn((v: unknown) => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Control value={value} onValueChange={(v: string, d: any) => { d.cancel(); setValue(v); }} />
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'x' } });
    await act(async () => {});
    console.log(label, '7 cancel controlled', attrs(screen.getByTestId('root')), 'validate', validate.mock.calls.length);
  });

  it('8. same value revalidation (validity-only change)', async () => {
    // simulate native validity change without value change: controlled consumer normalizes value
    const validate = vi.fn((v: unknown) => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Control type="number" value={value} onValueChange={setValue} />
        </Field.Root>
      );
    }
    render(<App />);
    const control = screen.getByRole<HTMLInputElement>('spinbutton');
    fireEvent.change(control, { target: { value: '1' } });
    await act(async () => {});
    const n = validate.mock.calls.length;
    // fire input event w/o value change
    fireEvent.input(control);
    await act(async () => {});
    console.log(label, '8 validity-only', 'first', n, 'after same-value input', validate.mock.calls.length);
  });

  it('9. initialValue type', async () => {
    let seen: any;
    render(
      <Field.Root data-testid="root">
        <Control value={5} onValueChange={() => {}} />
        <Field.Validity>{(s: any) => { seen = s; return null; }}</Field.Validity>
      </Field.Root>,
    );
    await act(async () => {});
    console.log(label, '9 initialValue', JSON.stringify(seen?.validity ? { iv: seen.initialValue, tv: typeof seen.initialValue } : seen));
  });
});
